parameters.jsCode:
const item = $input.first().json;
const emailBody = item.bodyPreview || item.body?.content || '';
const subject = item.subject || '';
const from = (item.from?.emailAddress?.address || item.sender?.emailAddress?.address || '').toLowerCase();

const isBNCR = from.includes('bncr') || from.includes('bancronacional') || subject.toLowerCase().includes('transferencia') || subject.toLowerCase().includes('sinpe') || emailBody.toLowerCase().includes('banco nacional');

if (!isBNCR) {
  return [{ json: { skip: true, reason: 'Not a BNCR email', from } }];
}

const fullText = subject + ' ' + emailBody;
const match = fullText.toUpperCase().match(/SC-[A-Z0-9]{4}/);
const referenceCode = match ? match[0] : null;

const amountMatch = fullText.match(/[\$₡]([\d,.]+)/);
const amount = amountMatch ? parseFloat(amountMatch[1].replace(/[,.]/g, '')) : null;

return [{ json: { referenceCode, amount, skip: false, emailSubject: subject, from, emailBody: emailBody.substring(0, 500) } }];

